const sessao = $('Split Sessões').item.json;
const perfil = $json.data;

let idade = null;
if (perfil.dataNascimento) {
  const nasc = new Date(perfil.dataNascimento);
  if (!isNaN(nasc.getTime())) {
    const hoje = new Date();
    idade = hoje.getFullYear() - nasc.getFullYear();
    const aindaNao = (hoje.getMonth() < nasc.getMonth()) || (hoje.getMonth() === nasc.getMonth() && hoje.getDate() < nasc.getDate());
    if (aindaNao) idade--;
  }
}

const outrasSessoes = (perfil.sessoes || []).filter(s => s.id !== sessao.id);
const totalAnteriores = outrasSessoes.length;
let tipoCliente = 'Novo Cliente';
if (totalAnteriores >= 10) tipoCliente = 'Cliente VIP';
else if (totalAnteriores >= 3) tipoCliente = 'Cliente Recorrente';
else if (totalAnteriores >= 1) tipoCliente = '2ª Visita';

const dataObj = new Date(sessao.data);
const dataCompleta = dataObj.toLocaleDateString('pt-PT', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const observacoesTxt = (perfil.observacoes || []).slice(0,5).map(o => `- ${o.texto}`).join('\n');

const preenchido = !!(sessao.fichaEstadoEmocional || sessao.fichaZonasTensao || sessao.fichaFoco || sessao.fichaCondicoesAlergias);

const fichaTexto = preenchido
  ? [
      sessao.fichaEstadoEmocional ? `Estado emocional: ${sessao.fichaEstadoEmocional}` : null,
      sessao.fichaZonasTensao ? `Zonas de tensão: ${sessao.fichaZonasTensao}` : null,
      sessao.fichaFoco ? `Foco/objetivo: ${sessao.fichaFoco}` : null,
      sessao.fichaCondicoesAlergias ? `Condições/alergias (desta sessão): ${sessao.fichaCondicoesAlergias}` : null,
