{
  "cliente_nome": "string",
  "tipo_cliente": "string",
  "contagem_visitas": number,
  "data_completa": "string",
  "hora": "string",
  "servico_hoje": "string",
  "ficha_preenchida": boolean,
  "alertas": "string ou null",
  "resumo_cliente": "string",
  "objetivo_sessao": "string",
  "continuidade_sessao_anterior": "string ou null",
  "mapa_corporal": [{ "zona": "string", "prioridade": "Alta ou Média", "motivo": "string", "abordagem": "string" }],
  "recomendacoes": ["string", "string", "string"],
  "nota_proxima_visita": "string"
}`;

return [{ json: { promptText, sessaoId: sessao.id, clienteId: sessao.clienteId, nomeCliente: perfil.nome, servico: sessao.servico, hora: sessao.hora, dataFmtCurta: dataObj.toLocaleDateString('pt-PT', { day: '2-digit', month: 'long' }), linkToken: sessao.linkToken } }];

